#include <cstdio>
#include <algorithm>
#include <cstring>
#define LL long long
using namespace std;
const int N=65;
const int MOD=1e9+7;
int m,len;
LL n,v[N];
struct MatrixNode
{
    int data[35][35];
    MatrixNode(){memset(data,0,sizeof(data));}
}matA,Nmat[N][35],S1[N][35],S2[N][35];

MatrixNode mat_product(MatrixNode a, MatrixNode b)
{
    MatrixNode c;
    for(int i=0;i<=m;i++)
        for(int j=0;j<=m;j++)
            for(int k=0;k<=m;k++)
                c.data[i][j]=(c.data[i][j]+(long long)a.data[i][k]*b.data[k][j]%MOD)%MOD;
    return c;
}

int main()
{
    scanf("%lld%d",&n,&m);
    v[0]=n; while(v[len]) v[len+1]=v[len]/m, v[len]%=m, len++;
    for(int i=0;i<len;i++)
    {
        if(i==0)
        {
            for(int j=0;j<m;j++)
            {
                Nmat[i][j].data[m][m]=1;
                for(int a=0;a<m;a++)
                {
                    if(a!=j) { Nmat[i][j].data[a][a]=1; continue; }
                    for(int b=0;b<=m;b++) Nmat[i][j].data[a][b]=1;
                }
            }
        }
        else
        {
            for(int j=0;j<m;j++)
            {
                if(j==0) Nmat[i][j]=S2[i-1][0];
                else Nmat[i][j]=mat_product(S2[i-1][j],S1[i-1][j-1]);
            }
        }
        S1[i][0]=Nmat[i][0];
        for(int j=1;j<m;j++) S1[i][j]=mat_product(S1[i][j-1],Nmat[i][j]);
        S2[i][m-1]=Nmat[i][m-1];
        for(int j=m-2;j>=0;j--) S2[i][j]=mat_product(Nmat[i][j],S2[i][j+1]);
    }
    for(int i=0;i<=m;i++) matA.data[0][i]=1;
    int j=0;
    for(int i=len-1;i>=0;i--)
        while(v[i]--) { matA=mat_product(matA,Nmat[i][j]); j=(j+1)%m; }
    printf("%d\n",matA.data[0][m]);
    return 0;
}
